<?php
/** Production pure normalizer: no MySQL, controller or visual-equivalence claim. */
define('BASEPATH',dirname(__DIR__).'/system/');define('APPPATH',dirname(__DIR__).'/application/');
require APPPATH.'services/CompanyLeadMetadata.php';
$checks=0;$check=static function(bool $valid,string $message)use(&$checks):void{if(!$valid)throw new RuntimeException($message);++$checks;};
$reject=static function(callable $work,string $message)use($check):void{$failed=false;try{$work();}catch(DomainException $error){$failed=true;}$check($failed,$message);};
$base=['version'=>1,'form_revision'=>str_repeat('a',64),'formats'=>['dateformat'=>'d/m/Y|%d/%m/%Y','time_format'=>'24']];$empty=CompanyLeadMetadata::normalize($base);
$check($empty['lead_value']===null&&$empty['lastcontact']===null&&$empty['tags']===[]&&$empty['custom_fields']===[],'Absent optional values do not become a fabricated zero, time or private field');
$check(CompanyLeadMetadata::normalize($empty)===$empty,'Normalized metadata round-trips deterministically');
foreach(['0'=>'0.00','1.5'=>'1.50','9999999999999.99'=>'9999999999999.99','-123.40'=>'-123.40']as$value=>$expected)$check(CompanyLeadMetadata::decimal((string)$value)===$expected,'Exact signed original DECIMAL value: '.$value);
foreach([0.1,'1e3','1.001','10000000000000.00','1,50',' 1.50',true,[]]as$value)$reject(fn()=>CompanyLeadMetadata::decimal($value),'Reject ambiguous or out-of-range monetary wire');
foreach(['2026-02-30 10:00:00','2026-11-05 24:00:00','0000-00-00 00:00:00','2026-11-05T10:00:00','05/11/2026 10:00:00']as$value)$reject(fn()=>CompanyLeadMetadata::datetime($value),'Only an exact normalized valid SQL datetime enters storage');
$currency=['id'=>1,'name'=>'BRL','symbol'=>'R$','decimal_separator'=>',','thousand_separator'=>'.','placement'=>'before','isdefault'=>1];
$now='2026-11-05 14:30:11';$today=CompanyLeadMetadata::normalize($base+['contacted_today'=>'1','lead_value'=>'123.45','title'=>'Diretor','default_language'=>'portuguese_br']);$first=CompanyLeadMetadata::values($today,$currency,$now);
$check($first['lastcontact']===$now&&$first['currency']===CompanyLeadMetadata::currency($currency)&&$first['lead_value']==='123.45','Today uses the writer-supplied clock and captures currency reference bytes');
$check(CompanyLeadMetadata::hash($today)===CompanyLeadMetadata::hash(CompanyLeadMetadata::normalize($today))&&!array_key_exists('lastcontact',$base),'Input hash is independent of later clock resolution');
$check(CompanyLeadMetadata::values($empty,$currency,$now)['currency']===null,'An absent value carries no invented currency amount');
$reject(fn()=>CompanyLeadMetadata::normalize($base+['contacted_today'=>1,'lastcontact'=>$now]),'Explicit time cannot silently compete with contacted-today');
$reject(fn()=>CompanyLeadMetadata::normalize($base+['country'=>-1]),'Invalid country id rejected before database lookup');
$reject(fn()=>CompanyLeadMetadata::normalize($base+['default_language'=>'../portuguese_br']),'Language path traversal rejected');
$reject(fn()=>CompanyLeadMetadata::normalize($base+['default_language'=>'fictional_language']),'Only the current real language catalogue is accepted');
foreach(['issuer_id'=>41,'is_public'=>1,'junk'=>1,'leadorder'=>1]as$field=>$value)$reject(fn()=>CompanyLeadMetadata::normalize($base+[$field=>$value]),'Unresolved access/status/order fields never become implicit metadata');
$check(CompanyLeadMetadata::tags(['São Paulo','Literal <tag>'])===['São Paulo','Literal <tag>'],'Tag text stays literal');
$reject(fn()=>CompanyLeadMetadata::tags(['São Paulo','são paulo']),'Case-folded duplicate tags rejected');
$field=NativeCompanyResourceId::encode('company_custom_field',27);$choices=['Literal "<choice>" & selected','Second choice'];$custom=CompanyLeadMetadata::customFields([$field=>$choices]);
$check($custom[$field]===$choices,'Multiple literal choices preserve their typed array');
$reject(fn()=>CompanyLeadMetadata::customFields([$field=>['bad'=>1]]),'Associative choice arrays are not silently reinterpreted');
$reject(fn()=>CompanyLeadMetadata::customFields([NativeCompanyResourceId::encode('company_lead',27)=>$choices]),'Lead ids cannot masquerade as field ids');
$check(CompanyLeadMetadata::websiteHref('https://example.invalid/path?a=1&b=2')==='https://example.invalid/path?a=1&b=2','Valid literal HTTP URL can be presented safely');
foreach(['javascript:alert(1)','data:text/html,<script>','example.invalid','https://bad.invalid/a b']as$value)$check(CompanyLeadMetadata::websiteHref($value)===null,'Untrusted schemes/bare text never produce executable links');
$columns=CompanyLeadMetadata::columns($first);$row=['lead_id'=>17,'issuer_id'=>41,'revision'=>1,'updated_at'=>$now]+$columns;
$check(CompanyLeadMetadata::fromRow($row)===$first,'Exact stored metadata and captured currency round-trip through the production reader');
$check(CompanyLeadMetadata::money('9999999999999.99',$currency)==='R$9.999.999.999.999,99'&&CompanyLeadMetadata::money('-1234.50',$currency)==='R$-1.234,50','Formatting never routes DECIMAL15,2 through a float');
$check(CompanyLeadMetadata::money(null,null)===''&&CompanyLeadMetadata::money('0',$currency)==='R$0,00','Absent amount remains distinct from explicit zero');
$check(CompanyLeadMetadata::currency(array_replace($currency,['symbol'=>'R$ ','thousand_separator'=>' ']))['symbol']==='R$ ','Currency snapshot preserves literal public catalogue spacing');
$check(CompanyLeadMetadata::customFields([$field=>"  first\nsecond  "])[$field]==="  first\nsecond  ",'Optional custom-field bytes are not trimmed by metadata normalization');
foreach(['currency_json'=>'{}','lead_value'=>'123.450','revision'=>0,'updated_at'=>'2026-02-30 10:00:00']as$name=>$value)$reject(fn()=>CompanyLeadMetadata::fromRow(array_replace($row,[$name=>$value])),'Corrupt stored metadata fails closed: '.$name);
$withoutCurrency=$row;unset($withoutCurrency['currency_json']);$reject(fn()=>CompanyLeadMetadata::fromRow($withoutCurrency),'Missing snapshot column is rejected without fallback');
foreach([['dateformat'=>'not-a-format','time_format'=>'24'],['dateformat'=>'d/m/Y|%d/%m/%Y','time_format'=>'25'],['dateformat'=>'d/m/Y|%d/%m/%Y','time_format'=>'24','issuer_id'=>54]]as$formats)$reject(fn()=>CompanyLeadMetadata::normalize(array_replace($base,['formats'=>$formats])),'Only the captured closed formatting contract enters the receipt hash');
$link=CompanyLeadMetadata::linkValue('<a href="https://example.invalid/?x=1&amp;y=2" onclick="alert(1)"><b>Literal &lt;link&gt;</b></a><script>alert(2)</script>');
$check($link===['text'=>'Literal <link>','href'=>'https://example.invalid/?x=1&y=2'],'Stored link is parsed inertly to text and allowed URL, without attributes or script');
$check(CompanyLeadMetadata::linkValue('<a href="javascript:alert(1)">Unsafe</a>')===['text'=>'Unsafe','href'=>null],'Unsafe stored link loses its executable destination');
echo 'Original Lead metadata normalization: '.$checks.' checks passed; pure production code, no SQL/browser claim.'.PHP_EOL;
